133	    /**
134	     * Look for water adjacent to the organism's current location
135	     * @return Where water was found, or null if it wasn't 
136	     */
137	    protected Location findWater() {
138	        Field field = getField();
139	        List<Location> adjacent = field.adjacentLocations(getLocation());
140	        Iterator<Location> it = adjacent.iterator();
141	        while(it.hasNext()){
142	            Location where = it.next();
143	            Object waterSource = field.getObjectAt(where);
144	            if(waterSource instanceof Lake) {
145	                Lake lake = (Lake) waterSource;
146	                if(lake.getVolume() <= 0){
147	                    lake.setDead();
148	                    return null;
149	                }
150	                int waterDrawn = Math.min(lake.getWaterValue(), lake.getVolume());
151	                setWaterLevel(getWaterLevel() + waterDrawn);
152	                lake.reduceVolume(waterDrawn);
153	                if (lake.getVolume() <= 0) {
154	                    lake.setDead();
155	                }
156	                return where;
157	            }
158	        }
159	        return null;
160	    }
